UPDATE scrape_task 
SET status = #{toStatus}, updated_at = CURRENT_TIMESTAMP 
WHERE id = #{id} AND status = #{fromStatus}

UPDATE scrape_task 
SET status = #{toStatus}, error_message = #{errorMessage}, updated_at = CURRENT_TIMESTAMP 
WHERE id = #{id} AND status = #{fromStatus}

mapper.select:
SELECT * FROM scrape_task 
WHERE game_id = #{gameId} 
ORDER BY priority ASC, order_index ASC

SELECT t.id AS "id", t.task_type AS "taskType", t.game_id AS "gameId", t.platform_id AS "platformId", t.media_type AS "mediaType", t.error_message AS "errorMessage", t.rom_filename AS "romFilename", t.updated_at AS "failedAt", g.name AS "gameName", p.name AS "platformName" FROM scrape_task t LEFT JOIN game g ON t.game_id = g.id LEFT JOIN platform p ON t.platform_id = p.id WHERE t.status = 'FAILED'
AND t.task_type = #{taskType}
ORDER BY t.updated_at DESC LIMIT #{limit}
